dark.customCSS:
:root {
	--aw-chrome: #120822;
	--aw-panel: #10071c;
	--aw-card: #1e1030;
	--aw-border: #4a2e62;
	--aw-fg: #f6eee6;
	--aw-muted: #c9b8d6;
	--aw-accent: #ff8a1e;
}

/* Reply text in the original's own text colours, in every mode (Typography's
   prose colours are fixed values, so they don't follow the gray scale) */
.markdown-prose, .markdown-prose-sm, .markdown-prose-xs {
	--tw-prose-body: var(--aw-fg) !important;
	--tw-prose-headings: var(--aw-fg) !important;
	--tw-prose-lead: var(--aw-muted) !important;
	--tw-prose-bold: var(--aw-fg) !important;
	--tw-prose-quotes: var(--aw-fg) !important;
	--tw-prose-code: var(--aw-fg) !important;
	--tw-prose-counters: var(--aw-muted) !important;
	--tw-prose-bullets: var(--aw-muted) !important;
	--tw-prose-captions: var(--aw-muted) !important;
	--tw-prose-hr: var(--aw-border) !important;
	--tw-prose-quote-borders: var(--aw-border) !important;
	--tw-prose-th-borders: var(--aw-border) !important;
	--tw-prose-td-borders: var(--aw-border) !important;
	--tw-prose-links: var(--aw-accent) !important;
	--tw-prose-kbd: var(--aw-fg) !important;
	--tw-prose-invert-body: var(--aw-fg) !important;
	--tw-prose-invert-headings: var(--aw-fg) !important;
	--tw-prose-invert-lead: var(--aw-muted) !important;
	--tw-prose-invert-bold: var(--aw-fg) !important;
	--tw-prose-invert-quotes: var(--aw-fg) !important;
	--tw-prose-invert-code: var(--aw-fg) !important;
	--tw-prose-invert-counters: var(--aw-muted) !important;
	--tw-prose-invert-bullets: var(--aw-muted) !important;
	--tw-prose-invert-captions: var(--aw-muted) !important;
	--tw-prose-invert-hr: var(--aw-border) !important;
	--tw-prose-invert-quote-borders: var(--aw-border) !important;
	--tw-prose-invert-th-borders: var(--aw-border) !important;
	--tw-prose-invert-td-borders: var(--aw-border) !important;
	--tw-prose-invert-links: var(--aw-accent) !important;
	--tw-prose-invert-kbd: var(--aw-fg) !important;
}

/* The original recolours the app to match its scene: these are its own sidebar,
   composer, card and accent colours, the same in every mode.
   !important only where Canvas FX clears a background. */
#message-input-container {
	background-color: color-mix(in oklab, var(--aw-card) 88%, transparent) !important;
	border-color: var(--aw-border) !important;
	backdrop-filter: blur(16px) saturate(1.1);
	transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
#message-input-container:focus-within {
	border-color: var(--aw-accent) !important;
	box-shadow: 0 0 0 3px color-mix(in oklab, var(--aw-accent) 22%, transparent);
}
.chat-user .rounded-3xl {
	background-color: color-mix(in oklab, var(--aw-card) 90%, transparent) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--aw-border) 60%, transparent);
}
#sidebar {
	background-color: color-mix(in oklab, var(--aw-chrome) 92%, transparent) !important;
	backdrop-filter: blur(22px) saturate(1.1);
	border-inline-end: 1px solid color-mix(in oklab, var(--aw-border) 70%, transparent);
}
#sidebar-chat-item.selected { background-color: color-mix(in oklab, var(--aw-accent) 16%, transparent); box-shadow: inset 2px 0 0 var(--aw-accent); }
.markdown-prose a { color: var(--aw-accent); text-decoration-color: color-mix(in oklab, var(--aw-accent) 55%, transparent); }
.markdown-prose strong { color: var(--aw-fg); }
.markdown-prose blockquote { border-inline-start-color: var(--aw-accent); }
.markdown-prose hr { border-color: var(--aw-border); }
html { scrollbar-color: var(--aw-border) transparent; }
::selection { background-color: color-mix(in oklab, var(--aw-accent) 26%, transparent); }

